// TRANSFORM MAPPING — Alur: Input → Proses → Output
// DFD: [Mahasiswa] → (Input Nilai) → (Hitung IP) → (Generate Transkrip) → [PDF]

// Level 0: Main Controller
class TranskriipController {
  async generateTranskrip(mahasiswaId) {
    // 1. INPUT MODULE — Ambil data
    const nilaiData = await this.inputModule.getNilai(mahasiswaId);

    // 2. TRANSFORM MODULE — Proses inti
    const ipSemester = this.transformModule.hitungIP(nilaiData);
    const rekap = this.transformModule.rekapMataKuliah(nilaiData);

    // 3. OUTPUT MODULE — Hasilkan output
    return this.outputModule.generatePDF({ ipSemester, rekap });
  }
}

// TRANSACTION MAPPING — Satu input, banyak jalur
// DFD: [User] → (Pilih Menu) → {Login / Daftar / Reset Password / Lihat Profil}
class AuthController {
  handle(action, payload) {
    const routes = {
      'login'          : () => this.loginService.execute(payload),
      'register'       : () => this.registerService.execute(payload),
      'resetPassword'  : () => this.resetService.execute(payload),
      'viewProfile'    : () => this.profileService.get(payload.userId)
    };
    return routes[action]?.() ?? this.errorHandler.unknownAction(action);
  }
}

